WITH a AS (
  SELECT 1 id FROM DUAL UNION ALL SELECT 2 id FROM DUAL
),
b AS (
  SELECT 1 id FROM DUAL UNION ALL SELECT 3 id FROM DUAL
)
SELECT COUNT(*) FROM a JOIN b ON a.id = b.id;

WITH a AS (
  SELECT 1 id FROM DUAL UNION ALL SELECT 2 id FROM DUAL
),
b AS (
  SELECT 1 id FROM DUAL UNION ALL SELECT 5 id FROM DUAL
)
SELECT COUNT(*) FROM a, b WHERE a.id(+) = b.id;

WITH a AS (
  SELECT 1 id, 'A1' name FROM DUAL UNION ALL SELECT 2 id, 'A2' name FROM DUAL
),
b AS (
  SELECT 1 id, 'B1' name FROM DUAL
)
SELECT COUNT(*) FROM a, b WHERE a.id = b.id(+);

WITH a AS (
  SELECT 1 id, 'A1' name FROM DUAL UNION ALL SELECT 2 id, 'A2' name FROM DUAL
),
b AS (
  SELECT 1 id, 'B1' name FROM DUAL
)
SELECT a.name, b.name AS b_name FROM a, b WHERE a.id = b.id(+)
ORDER BY a.name;

WITH a AS (
  SELECT 1 id, 'X' val FROM DUAL UNION ALL SELECT 2 id, 'Y' val FROM DUAL
),
b AS (
  SELECT 1 id FROM DUAL UNION ALL SELECT 2 id FROM DUAL
)
SELECT COUNT(*) FROM a NATURAL JOIN b;

WITH a AS (SELECT 1 id FROM DUAL UNION ALL SELECT 2 id FROM DUAL UNION ALL SELECT 3 id FROM DUAL),
     b AS (SELECT 'X' val FROM DUAL UNION ALL SELECT 'Y' val FROM DUAL)
SELECT COUNT(*) FROM a CROSS JOIN b;
